const generateMathProblems = (count, templates, min, max) => {
    const questions = [];
    for (let i = 0; i < count; i++) {
        const tmpl = templates[i % templates.length];
        let a = Math.floor(Math.random() * (max - min + 1)) + min;
        let b = Math.floor(Math.random() * (max - min + 1)) + min;
        if (a < b) [a, b] = [b, a];
        const data = tmpl(a, b);
        const opts = new Set([data.ans]);
        while (opts.size < 4) opts.add(data.ans + Math.floor(Math.random() * (5 - (-5) + 1)) + (-5));
        questions.push({ id: i, q: data.q, options: Array.from(opts).sort(() => Math.random() - 0.5), answer: data.ans.toString() });
    }
    return questions;
};

