    math: {
        beginner: {
            pure_math: (count) => {
                const questions = [];
                for (let i = 0; i < count; i++) {
                    const op = Math.random() > 0.5 ? '+' : '-';
                    let a = Math.floor(Math.random() * (20 - 1 + 1)) + 1;
                    let b = Math.floor(Math.random() * (20 - 1 + 1)) + 1;
                    let ans;
                    if (op === '+') { ans = a + b; }
                    else {
                        if (a < b) [a, b] = [b, a];
                        ans = a - b;
                    }
                    const opts = new Set([ans]);
                    while (opts.size < 4) { opts.add(ans + Math.floor(Math.random() * (5 - (-5) + 1)) + (-5)); }
                    const optsArr = Array.from(opts).filter(n => n >= 0);
                    while (optsArr.length < 4) optsArr.push(Math.floor(Math.random() * (40 - 0 + 1)) + 0);
                    questions.push({ id: i, q: `${a} ${op} ${b} = ?`, options: optsArr.sort(() => Math.random() - 0.5), answer: ans.toString() });
                }
                return questions;
            },
            problems: (count) => {
                const templates = [
                    (a, b) => ({ q: `${a} ta olmangiz bor, do'stingiz ${b} ta berdi. Jami nechta?`, ans: a + b }),
                    (a, b) => ({ q: `Sizda ${a} dollar bor. ${b} dollar ishlatdingiz. Qancha qoldi?`, ans: a - b }),
                    (a, b) => ({ q: `Daraxtda ${a} qush bor. ${b} tasi uchib ketdi. Nechta qoldi?`, ans: a - b }),
                    (a, b) => ({ q: `${a} quti, har birida ${b} ta qalam bor. Jami nechta?`, ans: a * b }),
                ];
                return generateMathProblems(count, templates, 1, 10);
            }
        },
        intermediate: {
            pure_math: (count) => {
                const questions = [];
                for (let i = 0; i < count; i++) {
                    const type = Math.floor(Math.random() * (3 - 1 + 1)) + 1;
                    let qText, ans;
                    if (type === 1) { // Mult
                        let a = Math.floor(Math.random() * (15 - 2 + 1)) + 2; let b = Math.floor(Math.random() * (15 - 2 + 1)) + 2; qText = `${a} * ${b} = ?`; ans = a * b;
                    } else if (type === 2) { // Div
                        let b = Math.floor(Math.random() * (12 - 2 + 1)) + 2; let userAns = Math.floor(Math.random() * (12 - 2 + 1)) + 2; let a = b * userAns; qText = `${a} / ${b} = ?`; ans = userAns;
                    } else { // Mixed
                        let a = Math.floor(Math.random() * (50 - 10 + 1)) + 10; let b = Math.floor(Math.random() * (20 - 5 + 1)) + 5; let c = Math.floor(Math.random() * (10 - 2 + 1)) + 2; qText = `${a} - ${b} + ${c} = ?`; ans = a - b + c;
                    }
                    const opts = new Set([ans]);
                    while (opts.size < 4) opts.add(ans + Math.floor(Math.random() * (10 - (-10) + 1)) + (-10));
                    questions.push({ id: i, q: qText, options: Array.from(opts).sort(() => Math.random() - 0.5), answer: ans.toString() });
                }
                return questions;
            },
            problems: (count) => {
                const templates = [
                    (a, b) => ({ q: `Avtomobil ${a} km/soat tezlikda ${b} soat yurdi. Masofa qancha?`, ans: a * b }),
                    (a, b) => ({ q: `To'g'ri to'rtburchakning eni ${a}sm, bo'yi ${b}sm. Yuzi qancha?`, ans: a * b }),
                    (a, b) => ({ q: `${a} ta kitob ${b * a} so'm. Bitta kitob narxi qancha?`, ans: b }),
                    (a, b) => ({ q: `Do'kon ${a} ta olma sotdi, bu jami olmalarning 50%i edi. Jami nechta olma bor edi?`, ans: a * 2 }),
                ];
                return generateMathProblems(count, templates, 5, 20);
            }
        },
        advanced: {
            pure_math: (count) => {
                const questions = [];
                for (let i = 0; i < count; i++) {
                    const type = Math.floor(Math.random() * (4 - 1 + 1)) + 1;
                    let qText, ans;
                    if (type === 1) { let x = Math.floor(Math.random() * (12 - 2 + 1)) + 2; let a = Math.floor(Math.random() * (9 - 2 + 1)) + 2; let b = Math.floor(Math.random() * (20 - 1 + 1)) + 1; let c = a * x + b; qText = `${a}x + ${b} = ${c}. x = ?`; ans = x; }
                    else if (type === 2) { let p = Math.floor(Math.random() * (9 - 1 + 1)) + 1 * 10; let val = Math.floor(Math.random() * (20 - 2 + 1)) + 2 * 10; qText = `${val} ning ${p}% i nechchi?`; ans = (val * p) / 100; }
                    else { let d = Math.floor(Math.random() * (15 - 1 + 1)) + 1; qText = `${d} sonining ikkilik kodi qanday?`; ans = d.toString(2); }

                    const opts = new Set([ans]);
                    if (typeof ans === 'string') { while (opts.size < 4) { let fake = (Math.floor(Math.random() * (15 - 1 + 1)) + 1).toString(2); if (fake !== ans) opts.add(fake); } }
                    else { while (opts.size < 4) opts.add(ans + Math.floor(Math.random() * (5 - (-5) + 1)) + (-5)); }
                    questions.push({ id: i, q: qText, options: Array.from(opts).sort(() => Math.random() - 0.5), answer: ans.toString() });
                }
                return questions;
            },
            problems: (count) => {
                const templates = [
                    (a, b) => ({ q: `Poyezd ${a} mil/soat tezlikda ${b} soat yurdi. Jami masofa?`, ans: a * b }),
                    (a, b) => ({ q: `To'rtburchak yuzi ${a * b}, tomoni ${a}. Ikkinchi tomoni?`, ans: b }),
                ];
                return generateMathProblems(count, templates, 20, 100);
            }
        }
    },
